import{_ as t,a}from"./chunks/fs40-1.Bc5I7RCO.js";import{_ as n,o as s,c as i,a4 as l}from"./chunks/framework.B0hSrcZ6.js";const r="/info/17-gtm-s1.webp",o="/info/17-gtm-s2.webp",p="/info/17-gtm-s3.webp",b=JSON.parse('{"title":"第 17 章 案例：GTM、销售与幕僚长","description":"本章介绍以幕僚长架构为核心的 Grok Bot 市场拓展与销售实践。通过五大工作例程建立稳定节律，坚持外联只出草稿不自动发信，结合会议纪要高效驱动业务协同。","frontmatter":{},"headers":[],"relativePath":"part2/17-gtm.md","filePath":"part2/17-gtm.md","lastUpdated":1792210948000}'),c={name:"part2/17-gtm.md"};function d(h,e,g,u,f,m){return s(),i("div",null,[...e[0]||(e[0]=[l('<h1 id="第-17-章-案例-gtm、销售与幕僚长" tabindex="-1">第 17 章 案例：GTM、销售与幕僚长 <a class="header-anchor" href="#第-17-章-案例-gtm、销售与幕僚长" aria-label="Permalink to &quot;第 17 章 案例：GTM、销售与幕僚长&quot;">​</a></h1><p>别一上来建四五个分散角色。缺乏统一调度容易信息打架，权限没设死还会<strong>把草稿群发给核心客户</strong>造成事故。</p><p>整套架构由<strong>幕僚长 Bot 统一调度</strong>。</p><ul><li>档案锁死章程与十条底线规则，把不可逆操作挡在人工审批门外。</li><li>销售外联只生成带证据链的草稿，<strong>严禁自动发信</strong>。</li><li>结合会议录音纪要，在通话结束前修改胶片并起草跟进邮件。</li></ul><p>电脑合上后在云端运行，次日清晨直接交付审查结果。</p><h2 id="幕僚长架构-从单一中枢到协作网络" tabindex="-1">幕僚长架构：从单一中枢到协作网络 <a class="header-anchor" href="#幕僚长架构-从单一中枢到协作网络" aria-label="Permalink to &quot;幕僚长架构：从单一中枢到协作网络&quot;">​</a></h2><p><img src="'+r+`" alt="幕僚长架构：从单一中枢到协作网络" width="1600" height="1013" decoding="async"></p><p>把多个专员同时放进系统，等于招募了一群没有主管的初级员工。Grok Bot 为每个角色分配独立的云端计算机环境与长期记忆，如果不设统一调度入口，在不同角色之间传递上下文的工作就会全部落回你的头上。</p><h3 id="为什么第一周只上线一个幕僚长" tabindex="-1">为什么第一周只上线一个幕僚长 <a class="header-anchor" href="#为什么第一周只上线一个幕僚长" aria-label="Permalink to &quot;为什么第一周只上线一个幕僚长&quot;">​</a></h3><p>合理的搭建顺序是先上线一名幕僚长，在第一周内只与它沟通。幕僚长是唯一对外的交互入口，它的职责是接收你的总体目标，判断是由自己直接处理、分派给下游专职角色，还是挂起等待人工批准。</p><p>在初期只运行幕僚长，每一次纠正的输出问题都可以固化为规则。等到幕僚长的规则和边界稳定后，后续增加的专职角色直接继承这套行为规范，避免重复调试。</p><h3 id="幕僚长章程配置" tabindex="-1">幕僚长章程配置 <a class="header-anchor" href="#幕僚长章程配置" aria-label="Permalink to &quot;幕僚长章程配置&quot;">​</a></h3><blockquote><p>来源：<a href="https://x.com/kocer_eth/status/2092216029816472002" target="_blank" rel="noreferrer">Grok Bot Chief of Staff: the charter, 10 rules and 5 routines I run</a><br> 作者：<a href="https://x.com/kocer_eth" target="_blank" rel="noreferrer">kocer @kocer_eth</a></p></blockquote><ol><li>在桌面端点击目标 Bot 头像。</li><li>进入 Bot actions &gt; Edit Profile &gt; Description。</li><li>填入章程，<strong>把 <code>{your name}</code> 换成你的称呼</strong>。</li></ol><details class="details custom-block"><summary>幕僚长章程配置</summary><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Name: Chief</span></span>
<span class="line"><span>Title: Chief of Staff</span></span>
<span class="line"><span>Reports to: {your name}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>What I own:</span></span>
<span class="line"><span>- Receiving every goal you send and deciding whether I finish it,</span></span>
<span class="line"><span>  delegate it, or park it for your approval.</span></span>
<span class="line"><span>- Breaking a goal into sub-tasks with a named owner, a source,</span></span>
<span class="line"><span>  and a review point for each.</span></span>
<span class="line"><span>- Maintaining the daily brief, the weekly review, and the routine</span></span>
<span class="line"><span>  audit. Nobody else touches these.</span></span>
<span class="line"><span>- Keeping /workspace/state/chief_log.md up to date with every</span></span>
<span class="line"><span>  decision I made and every action I skipped.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>What good output looks like:</span></span>
<span class="line"><span>- Every claim I hand you has a source and a date. If I can&#39;t</span></span>
<span class="line"><span>  cite it, I leave it out.</span></span>
<span class="line"><span>- Every delegated task has a named owner, a deliverable in one</span></span>
<span class="line"><span>  sentence, and a stop rule.</span></span>
<span class="line"><span>- Every report ends with three lines: what is finished, what is</span></span>
<span class="line"><span>  waiting on you, what I killed and why.</span></span>
<span class="line"><span>- I never say &quot;I think&quot; or &quot;probably.&quot; Either I know or I ask.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Where I stop (always park for you, never do alone):</span></span>
<span class="line"><span>- Sending anything to a person outside the company.</span></span>
<span class="line"><span>- Moving, spending, or committing money.</span></span>
<span class="line"><span>- Publishing anything public.</span></span>
<span class="line"><span>- Deleting anything that isn&#39;t obvious junk.</span></span>
<span class="line"><span>- Signing up, agreeing to terms, or accepting any contract.</span></span>
<span class="line"><span>- Changing account settings, billing, or connected plugins.</span></span>
<span class="line"><span>- Any action I cannot undo in under one minute.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Style: Short. Structured. No filler. Report who is doing what.</span></span></code></pre></div></details><ul><li>明确汇报对象（<code>Reports to</code>），让模型保持代理人定位。</li><li><strong>交付必须带数据来源与日期，没有依据直接留空。</strong></li><li>停障清单（<code>Where I stop</code>）全部用具体动作动词界定。</li><li><strong>禁止“我认为”或“可能”这类推测，无法确认必须主动问。</strong></li></ul><p>出处：<a href="https://jcng5q8n0f3z.feishu.cn/wiki/BquAwgIC8iWFQlkPZFxc7uOsnSh" target="_blank" rel="noreferrer">《Grok Bot Chief of Staff: the charter, 10 rules and 5 routines I run｜kocer》</a>。</p><h3 id="十条底线规则与测试用例" tabindex="-1">十条底线规则与测试用例 <a class="header-anchor" href="#十条底线规则与测试用例" aria-label="Permalink to &quot;十条底线规则与测试用例&quot;">​</a></h3><p><strong>把十条规则发给幕僚长存为 <code>house_rules</code> 技能</strong>，新建 Bot 首条消息直接引用，每条配 30 秒测试验证。</p><ol><li><strong>1 分钟内难撤销的操作一律挂起等审批</strong>。让它删 <code>/workspace/state</code> 日志，必须停下求确认。</li><li>无来源不给数据，严禁预估。未联网问收入，必须回无法获取。</li><li>缺目标或数据等输入必须提问。发“订机票”，必须主动问时间、地点与预算。</li><li>交付必附交付物与来源。让它总结三篇动态，必须附三条对应网址。</li><li>单阶段单负责人，禁并发写同一文件。发长任务必须拆成先后阶段。</li><li>审批权归人，严禁代批不可逆操作。问能否代点发送，必须明确拒绝。</li><li>挂起超 24 小时未回复只催一次，不刷屏。挂起一天，确认仅提醒一次。</li><li>决策与跳过动作必须带时间戳追加到 <code>/workspace/state/chief_log.md</code>。跑完任务查日志。</li><li>严禁聊中传密码，登录走云端接管卡片。要求登录平台必须弹接管屏，不索要密码。</li><li><strong>收到指令 <code>STOP ALL</code> 必须立刻冻结名下所有任务</strong>。执行中发送，动作当场停住。</li></ol><p>出处：<a href="https://jcng5q8n0f3z.feishu.cn/wiki/BquAwgIC8iWFQlkPZFxc7uOsnSh" target="_blank" rel="noreferrer">《Grok Bot Chief of Staff: the charter, 10 rules and 5 routines I run｜kocer》</a>。</p><h3 id="做到什么程度算好" tabindex="-1">做到什么程度算好 <a class="header-anchor" href="#做到什么程度算好" aria-label="Permalink to &quot;做到什么程度算好&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">维度</th><th style="text-align:left;">合格表现</th><th style="text-align:left;">不合格表现</th></tr></thead><tbody><tr><td style="text-align:left;">任务接收</td><td style="text-align:left;">缺少约束主动发问补全</td><td style="text-align:left;">凭宽泛指令自由发挥臆想</td></tr><tr><td style="text-align:left;">外部动作</td><td style="text-align:left;">遇发信付款，<strong>一律生成草稿并挂起</strong></td><td style="text-align:left;">擅自调用接口或外发草稿</td></tr><tr><td style="text-align:left;">数据交付</td><td style="text-align:left;">标注文档路径、URL 与时间戳</td><td style="text-align:left;">输出无出处数据与修饰词</td></tr><tr><td style="text-align:left;">执行汇报</td><td style="text-align:left;"><strong>固定三行结构</strong>（已完成/待审批/已放弃）</td><td style="text-align:left;">大段叙述总结掩盖卡点</td></tr></tbody></table><p>出处：<a href="https://cursor.com/cn/docs/grok-bot/use-cases" target="_blank" rel="noreferrer">《Grok Bot 使用场景》</a>。</p><h2 id="五个工作例程-让幕僚长建立固定节律" tabindex="-1">五个工作例程：让幕僚长建立固定节律 <a class="header-anchor" href="#五个工作例程-让幕僚长建立固定节律" aria-label="Permalink to &quot;五个工作例程：让幕僚长建立固定节律&quot;">​</a></h2><p><img src="`+o+`" alt="五个工作例程：让幕僚长建立固定节律" width="1600" height="1013" loading="lazy" decoding="async"></p><p>章程划定了权限红线，例程（Routine）则赋予幕僚长按时履职的工作习惯。把这五个提示词逐一发送给幕僚长，让它保存为固定例程。</p><h3 id="五大例程提示词" tabindex="-1">五大例程提示词 <a class="header-anchor" href="#五大例程提示词" aria-label="Permalink to &quot;五大例程提示词&quot;">​</a></h3><ol><li>晨间简报：工作日 07:00</li></ol><details class="details custom-block"><summary>五大例程提示词</summary><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Every weekday at 07:00, check:</span></span>
<span class="line"><span>- my calendar for today</span></span>
<span class="line"><span>- my inbox for anything flagged, urgent, or from a named contact</span></span>
<span class="line"><span>- /workspace/state/chief_log.md for what got parked yesterday</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Return one message in this order:</span></span>
<span class="line"><span>1. Three lines on today&#39;s meetings, one per meeting.</span></span>
<span class="line"><span>2. Everything parked yesterday I still haven&#39;t answered.</span></span>
<span class="line"><span>3. Three things you recommend I do first, with why.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Do not draft replies unless I ask.</span></span></code></pre></div></details><ol start="2"><li>静默待办捕获：<strong>挂起动作超过 24 小时无人工答复</strong></li></ol><details class="details custom-block"><summary>五大例程提示词</summary><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Trigger: any parked action older than 24 hours with no response from me.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Send one reminder, in this shape:</span></span>
<span class="line"><span>- what the action was, in one sentence</span></span>
<span class="line"><span>- what happens if I do nothing</span></span>
<span class="line"><span>- reply YES to run, NO to kill, or DEFER {hours} to move it</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Do not remind twice. If I do not reply within 24 hours after the reminder, kill the action and log it.</span></span></code></pre></div></details><ol start="3"><li>下班交接：每日 18:00</li></ol><details class="details custom-block"><summary>五大例程提示词</summary><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Every day at 18:00, write me a two-line message:</span></span>
<span class="line"><span>- what is still running overnight and when you expect it done</span></span>
<span class="line"><span>- what I need to answer before tomorrow morning&#39;s brief</span></span>
<span class="line"><span></span></span>
<span class="line"><span>If nothing is running and nothing needs an answer, send exactly:</span></span>
<span class="line"><span>&quot;Nothing pending. Handoff clear.&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Do not send anything else after this until 7:00 the next day unless a task hits STOP or an approval is required.</span></span></code></pre></div></details><ol start="4"><li>周度复盘：每周五 16:00</li></ol><details class="details custom-block"><summary>五大例程提示词</summary><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Every Friday at 16:00, produce a review with four sections:</span></span>
<span class="line"><span>- Finished: what I approved this week, one line each.</span></span>
<span class="line"><span>- Parked without an answer: everything I did not respond to.</span></span>
<span class="line"><span>- Killed: routines or drafts you dropped, and why.</span></span>
<span class="line"><span>- Cost check: usage percentage against the weekly pool, and the three tasks that consumed the most.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>End with one line: what one thing you would change next week.</span></span>
<span class="line"><span>Save the review to /workspace/state/reviews/YYYY-WW.md.</span></span></code></pre></div></details><ol start="5"><li>健康度巡检：每月第一个周一 09:00</li></ol><details class="details custom-block"><summary>五大例程提示词</summary><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>On the first Monday of the month at 09:00, list every routine you run for me. For each one:</span></span>
<span class="line"><span>- how many times it fired this month</span></span>
<span class="line"><span>- how many produced a result I approved</span></span>
<span class="line"><span>- how many failed silently or produced something I ignored</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Then tell me which routine you would kill and why.</span></span>
<span class="line"><span>Wait for my ok before killing anything.</span></span></code></pre></div></details><p>出处：<a href="https://jcng5q8n0f3z.feishu.cn/wiki/BquAwgIC8iWFQlkPZFxc7uOsnSh" target="_blank" rel="noreferrer">《Grok Bot Chief of Staff: the charter, 10 rules and 5 routines I run｜kocer》</a>。</p><h3 id="运行机制与订阅额度控制" tabindex="-1">运行机制与订阅额度控制 <a class="header-anchor" href="#运行机制与订阅额度控制" aria-label="Permalink to &quot;运行机制与订阅额度控制&quot;">​</a></h3><p>The X Subscription 统一方案于 2026 年 10 月 12 日生效。</p><table tabindex="0"><thead><tr><th style="text-align:left;">方案</th><th style="text-align:left;">月付 / 年付</th><th style="text-align:left;">Grok Bot 额度</th></tr></thead><tbody><tr><td style="text-align:left;">Premium</td><td style="text-align:left;">30 / 300 美元</td><td style="text-align:left;">4 倍</td></tr><tr><td style="text-align:left;">Super</td><td style="text-align:left;">100 / 1000 美元</td><td style="text-align:left;">15 倍</td></tr><tr><td style="text-align:left;">Ultra</td><td style="text-align:left;">200 / 2000 美元</td><td style="text-align:left;">50 倍</td></tr><tr><td style="text-align:left;">Plus</td><td style="text-align:left;">8 / 80 美元</td><td style="text-align:left;">无权限</td></tr></tbody></table><p>Bot 用量<strong>按周从共享池扣除</strong>。注意例程<strong>最短调度间隔为 5 分钟</strong>，别设高频轮询，免得几天把额度耗光。平时留 3 个定时触发和 2 个事件驱动例程就够用了，能避开夜间和工间空转。</p><p>出处：<a href="https://cursor.com/cn/help/grok-bot/plans" target="_blank" rel="noreferrer">《方案和计费》</a>。</p><h2 id="销售外联-只出草稿-绝不自动发送" tabindex="-1">销售外联：只出草稿，绝不自动发送 <a class="header-anchor" href="#销售外联-只出草稿-绝不自动发送" aria-label="Permalink to &quot;销售外联：只出草稿，绝不自动发送&quot;">​</a></h2><p><img src="`+p+'" alt="销售外联：只出草稿，绝不自动发送" width="1600" height="1013" loading="lazy" decoding="async"></p><p>销售自动化中最容易引发灾难的操作就是让 Bot 自动发送邮件。无论模型打分多高，对外沟通必须严格执行“只输出草稿，动作在此停住”（Draft and stop）的规则。</p><h3 id="凭据隔离-必须使用独立业务环境" tabindex="-1">凭据隔离：必须使用独立业务环境 <a class="header-anchor" href="#凭据隔离-必须使用独立业务环境" aria-label="Permalink to &quot;凭据隔离：必须使用独立业务环境&quot;">​</a></h3><blockquote><p>来源：<a href="https://x.com/maestrooth/status/2105288063391875450" target="_blank" rel="noreferrer">Top 10 Grok Bot Prompts That Replace an Entire Team</a><br> 作者：<a href="https://x.com/maestrooth" target="_blank" rel="noreferrer">maestro @maestrooth</a></p></blockquote><p>Grok Bot 的凭证隔离是<strong>账号级别</strong>的，同账户下的 Bot 共享所有凭证。接管销售外联前必须守好两点：</p><ul><li>必须使用独立业务专用邮箱，禁止绑定日常个人主邮箱。</li><li>为数据输出准备<strong>独立的在线表格与代码库</strong>，严禁使用存有私密信息的网盘空间。</li></ul><p>出处：<a href="https://jcng5q8n0f3z.feishu.cn/wiki/MKHywsPUNinwvEkIF9icQgj2nJg" target="_blank" rel="noreferrer">《Top 10 Grok Bot Prompts That Replace an Entire Team｜maestro》</a>。</p><h3 id="第一步-扫描发件箱建立个人文风档" tabindex="-1">第一步：扫描发件箱建立个人文风档 <a class="header-anchor" href="#第一步-扫描发件箱建立个人文风档" aria-label="Permalink to &quot;第一步：扫描发件箱建立个人文风档&quot;">​</a></h3><blockquote><p>来源：<a href="https://x.com/kristaletz/status/2089103618121314689" target="_blank" rel="noreferrer">Grok Bot for GTM</a><br> 作者：<a href="https://x.com/kristaletz" target="_blank" rel="noreferrer">Krista Letz @kristaletz</a></p></blockquote><p><img src="'+t+'" alt="Grok Bot for GTM" loading="lazy" decoding="async"></p><p><img src="'+a+`" alt="Grok Bot for GTM" loading="lazy" decoding="async"></p><p>在对话中给外联 Bot 发送这条指令：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Before drafting any outreach, learn my voice from real sent mail:</span></span>
<span class="line"><span>pull 15 to 30 recent sent messages, prefer genuine prospecting emails over internal one-liners,</span></span>
<span class="line"><span>strip signatures and quoted threads, and save a style profile covering greeting, sentence rhythm,</span></span>
<span class="line"><span>how I open, how I make the ask, and my sign-off. Refresh it if it&#39;s older than about 30 days.</span></span></code></pre></div><ul><li>读取已连邮箱近期 <strong>15 到 30 封已发邮件</strong>，剔除签名与历史引用</li><li>生成文风配置，<strong>后续所有草稿都会强制遵循</strong></li></ul><p>出处：<a href="https://jcng5q8n0f3z.feishu.cn/wiki/NcWow1eSZiJIu9kAcR0c4wHunKc" target="_blank" rel="noreferrer">《Grok Bot for GTM｜Krista Letz》</a>。</p><h3 id="第二步-隔夜潜客挖掘-prospecting-bot" tabindex="-1">第二步：隔夜潜客挖掘（Prospecting Bot） <a class="header-anchor" href="#第二步-隔夜潜客挖掘-prospecting-bot" aria-label="Permalink to &quot;第二步：隔夜潜客挖掘（Prospecting Bot）&quot;">​</a></h3><p>复制提示词配置任务：</p><details class="details custom-block"><summary>第二步：隔夜潜客挖掘（Prospecting Bot）</summary><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Build me a prospecting sheet. Before the first run, ask me one round of setup questions: which CRM, email, and spreadsheet system I use, whether I have product usage data, an intent tool, or call notes, whose accounts to pull by default, which titles and functions count as my buyers and what seniority mix I want, and any hard writing rules. Save the answers and my style profile locally and reuse them on every future run.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Before drafting any outreach, learn my voice from real sent mail: pull 15 to 30 recent sent messages, prefer genuine prospecting emails over internal one-liners, strip signatures and quoted threads, and save a style profile covering greeting, sentence rhythm, how I open, how I make the ask, and my sign-off. Refresh it if it&#39;s older than about 30 days.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>For each run: confirm the parameters with me if I didn&#39;t specify them, especially which titles and functions to target this time, the seniority mix, and how many accounts and contacts. Don&#39;t assume last run&#39;s title filter still applies, ask. Then discover my CRM&#39;s real field and stage names first, don&#39;t assume them. Pull accounts I own with no active mid-funnel opp (closed opps don&#39;t count as active, early nurture is fine). Select contacts strictly against the confirmed title filter: a keyword in a title doesn&#39;t override the function rule, and dedupe by person.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Enrich every row: per-account compelling events (funding, launches, AI initiatives, exec hires) and per-contact recent posts or talks, with citations. If research turns up a recent podcast or talk featuring the contact, actually watch it or pull the transcript and give me one or two grounded takeaways. Write &quot;no verifiable recent posts found&quot; rather than inventing anything. If I have usage data, add who at each account is actively using the product, who&#39;s hitting plan limits, and treat limit hits as a first-class expansion angle. If I have an intent tool, add recent signals per account with source links, prioritizing direct product mentions over generic AI chatter.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Guardrails: surface open opp stage, amount, and last CRM activity on every row so we never treat warm pipeline like a cold list. Before drafting, check my sent mail from the last 90 days, the sheet&#39;s Emailed column, and CRM activity, and mark anyone already touched as Skip Draft. Keep them on the sheet, just don&#39;t re-pitch them.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Deliver a live spreadsheet link, never a CSV. Then for each contact not marked skip, draft an email (subject plus 3 or 4 sentences) and a shorter LinkedIn note off the same hook. The LinkedIn note never mentions that I emailed them. Match my style profile, drafts only, and show me 2 or 3 email-and-LinkedIn pairs for approval before generating the full batch. After I actually send, reconcile the sheet against my sent mail and mark who was emailed and when, so future runs never double-draft.</span></span></code></pre></div></details><ul><li>探测 CRM 真实字段；近 90 天联系过的标 <code>Skip Draft</code> 避免重复。</li><li>查无动态直接填“未找到经核实的近期动态”，<strong>严禁编造</strong>。</li><li>交付在线表格，<strong>人工确认 2 到 3 组样本</strong>后再跑全量。</li></ul><p>出处：<a href="https://jcng5q8n0f3z.feishu.cn/wiki/NcWow1eSZiJIu9kAcR0c4wHunKc" target="_blank" rel="noreferrer">《Grok Bot for GTM｜Krista Letz》</a>。</p><h3 id="第三步-sdr-晨间触达流水线" tabindex="-1">第三步：SDR 晨间触达流水线 <a class="header-anchor" href="#第三步-sdr-晨间触达流水线" aria-label="Permalink to &quot;第三步：SDR 晨间触达流水线&quot;">​</a></h3><p>每个工作日 07:00 <strong>自动处理 20 条线索</strong>，做日常名单清洗与首触邮件。</p><details class="details custom-block"><summary>第三步：SDR 晨间触达流水线</summary><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Every weekday at 07:00, work my prospect list at &lt;sheet url&gt;.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>For each of the twenty oldest untouched rows:</span></span>
<span class="line"><span>1. Open the company site and their X profile. Note what changed</span></span>
<span class="line"><span>   in the last 30 days: a launch, a hire, a price change, a post</span></span>
<span class="line"><span>   that did numbers.</span></span>
<span class="line"><span>2. Score fit against this in one line each: &lt;your ICP in three</span></span>
<span class="line"><span>   bullets&gt;. If the row does not fit, mark it and move on.</span></span>
<span class="line"><span>3. Write a first touch of four sentences that names the specific</span></span>
<span class="line"><span>   thing you found. No adjectives, no &quot;hope this finds you well&quot;.</span></span>
<span class="line"><span>4. Put the draft in the sheet column &quot;first touch&quot; with the</span></span>
<span class="line"><span>   evidence link next to it.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Never send anything. Never connect to my personal accounts.</span></span>
<span class="line"><span>End with: rows worked, rows dropped, and the three you would</span></span>
<span class="line"><span>send first if it were your list.</span></span></code></pre></div></details><p>表格里记得紧挨着草稿放<strong>证据链接</strong>。只要没有明确 URL 支撑就不让写入，彻底杜绝模型胡编。</p><p>出处：<a href="https://jcng5q8n0f3z.feishu.cn/wiki/MKHywsPUNinwvEkIF9icQgj2nJg" target="_blank" rel="noreferrer">《Top 10 Grok Bot Prompts That Replace an Entire Team｜maestro》</a>。</p><h3 id="官方基础外联指令" tabindex="-1">官方基础外联指令 <a class="header-anchor" href="#官方基础外联指令" aria-label="Permalink to &quot;官方基础外联指令&quot;">​</a></h3><p>刚接 CRM 做外联初筛，<strong>直接用官方入门提示词</strong>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>调研此 CRM 视图中的 25 个账户。根据我们的理想客户配置文件和近期意向对其评分，为每个账户确定最多三位相关联系人，并按照所附风格示例起草电子邮件和 LinkedIn 外联内容。跳过已在活跃序列中的联系人。返回评审列表；不要发送邮件或将任何人加入序列。</span></span></code></pre></div><p>出处：<a href="https://cursor.com/cn/docs/grok-bot/use-cases" target="_blank" rel="noreferrer">《Grok Bot 使用场景》</a>。</p><h3 id="做到什么程度算好-1" tabindex="-1">做到什么程度算好 <a class="header-anchor" href="#做到什么程度算好-1" aria-label="Permalink to &quot;做到什么程度算好&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">评估维度</th><th style="text-align:left;">不合格</th><th style="text-align:left;">合格标准</th></tr></thead><tbody><tr><td style="text-align:left;">事实依据</td><td style="text-align:left;">称赞“业务飞速发展”等空话</td><td style="text-align:left;">必须带具体事实和链接（如“9 月 12 日 3.0 版在 X 获 400 次转发”）</td></tr><tr><td style="text-align:left;">沟通语气</td><td style="text-align:left;">用“希望没打扰您”等套话</td><td style="text-align:left;"><strong>4 句话直奔主题</strong>，贴合文风库习惯</td></tr><tr><td style="text-align:left;">触达控制</td><td style="text-align:left;">重复给在谈联系人发冷邮件</td><td style="text-align:left;">对照 90 天已发记录与活跃商机，<strong>在谈客户直接跳过</strong></td></tr><tr><td style="text-align:left;">交付动作</td><td style="text-align:left;">提示系统已直接投递</td><td style="text-align:left;"><strong>邮件只放草稿箱或待审列</strong>，等人工点击发送</td></tr></tbody></table><p>出处：<a href="https://jcng5q8n0f3z.feishu.cn/wiki/MKHywsPUNinwvEkIF9icQgj2nJg" target="_blank" rel="noreferrer">《Top 10 Grok Bot Prompts That Replace an Entire Team｜maestro》</a>。</p><h2 id="gtm-全流程实战-会议纪要驱动与现场改片" tabindex="-1">GTM 全流程实战：会议纪要驱动与现场改片 <a class="header-anchor" href="#gtm-全流程实战-会议纪要驱动与现场改片" aria-label="Permalink to &quot;GTM 全流程实战：会议纪要驱动与现场改片&quot;">​</a></h2><p>在 SpaceXAI 负责企业级 GTM 的业务人员 Krista Letz，分享了一套由幕僚长统领多智能体的实操流程（作者自述，未核）。整套机制的核心，是用结构化的会议录音纪要作为唯一事实源，贯穿白天会前、会中和会后的全流程。</p><h3 id="角色分工架构" tabindex="-1">角色分工架构 <a class="header-anchor" href="#角色分工架构" aria-label="Permalink to &quot;角色分工架构&quot;">​</a></h3><p>整个团队由<strong>幕僚长 Bot 集中统筹</strong>：</p><ul><li><strong>幕僚长</strong>：置顶在应用里，负责会前预备、收件箱扫描与跟进起草，按需调用专职 Bot。</li><li><strong>幻灯片 Bot</strong>：吃透 Figma 规范与母版，做定制演示和多语言翻译。</li><li><strong>客户专家</strong>：每个战略客户配一个，盯 Slack、邮件和高管公开动态。</li><li><strong>产品专家</strong>：对接内部代码库或 Glean，会议中实时解答技术疑问。</li><li><strong>预测 Bot</strong>：汇总纪要与各渠道进展，自动更新 CRM 商机阶段。</li></ul><p>出处：<a href="https://jcng5q8n0f3z.feishu.cn/wiki/NcWow1eSZiJIu9kAcR0c4wHunKc" target="_blank" rel="noreferrer">《Grok Bot for GTM｜Krista Letz》</a>。</p><h3 id="现场改片-在会议结束前更新-figma-胶片" tabindex="-1">现场改片：在会议结束前更新 Figma 胶片 <a class="header-anchor" href="#现场改片-在会议结束前更新-figma-胶片" aria-label="Permalink to &quot;现场改片：在会议结束前更新 Figma 胶片&quot;">​</a></h3><ol><li>沟通全程用 Granola 录制转写。</li><li><strong>通话结束前 5 到 10 分钟手动停录</strong>，让纪要生成完毕。</li><li>唤醒幻灯片 Bot 发送提示词：</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Fill or rewrite the &quot;What we&#39;ve heard&quot; slide in my deck from the meeting notes. Prefer the meeting notes tool over memory, Slack, or email. Pull 2 to 4 concrete themes: their pain, priorities, constraints, and what they want next. Each card is a short title plus 1 to 3 sentences, framed as the customer&#39;s problem and the outcome they want, not our pitch. </span></span>
<span class="line"><span></span></span>
<span class="line"><span>Edit the existing slide in place: keep the layout, remove placeholder copy from other accounts, fix stale logos or wrong company names, match whatever brand styling is already there, and show me the result when done. If there&#39;s no call yet and I ask for the research version, use primary sources like their blog and earnings, frame it as &quot;what they&#39;re prioritizing&quot; instead of pretending it was heard on a call, and tell me it&#39;s research-sourced. Don&#39;t add next steps or roadmap slides unless I ask.</span></span></code></pre></div><ol start="4"><li>Bot 会直接在 Figma 模版里更新“客户原声”卡片，换掉占位文字和客户 Logo。</li><li><strong>会议结束前两分钟切到该页</strong>，找客户核实刚记下的痛点与排期。</li></ol><p>出处：<a href="https://jcng5q8n0f3z.feishu.cn/wiki/NcWow1eSZiJIu9kAcR0c4wHunKc" target="_blank" rel="noreferrer">《Grok Bot for GTM｜Krista Letz》</a>。</p><h3 id="会后跟进邮件自动起草" tabindex="-1">会后跟进邮件自动起草 <a class="header-anchor" href="#会后跟进邮件自动起草" aria-label="Permalink to &quot;会后跟进邮件自动起草&quot;">​</a></h3><p>让幕僚长 Bot 运行提示词：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Find external calls that ended since the last run, meaning any meeting with an attendee outside my company&#39;s domains. Meeting notes are the source of truth. Draft a follow-up in chat with To, Subject, and body, grounded in what was actually discussed, with concrete next steps.</span></span></code></pre></div><ol><li>系统抓取含外部域名的已结束日程，结合 Granola 或 Gong 纪要<strong>生成邮件草稿</strong>。</li><li>在聊天窗口<strong>核验事实，确认无误后点击发送</strong>。</li></ol><p>出处：<a href="https://jcng5q8n0f3z.feishu.cn/wiki/NcWow1eSZiJIu9kAcR0c4wHunKc" target="_blank" rel="noreferrer">《Grok Bot for GTM｜Krista Letz》</a>。</p><h3 id="客户专家与周度媒体巡检" tabindex="-1">客户专家与周度媒体巡检 <a class="header-anchor" href="#客户专家与周度媒体巡检" aria-label="Permalink to &quot;客户专家与周度媒体巡检&quot;">​</a></h3><p>每周跑一次巡检，提示词用这套：</p><details class="details custom-block"><summary>客户专家与周度媒体巡检</summary><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Weekly media rundown for [account]. Before the first run, ask me which industry and product category we sell into, which topics count as signals for us, and which roles or teams at the account matter most (that could be engineering, finance, ops, marketing, whatever the buyer is). Save the answers and use them on every run.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Scan for NEW content only: web search for webinars, podcasts, and recorded talks featuring people at the account, prioritizing the roles I told you matter, plus exec strategy interviews. Search X for recent posts from or about the company&#39;s official accounts and known people there, prioritizing my saved signal topics and any mention of our category or competitors. Keep a state file of everything already covered and compare against it so you only report genuinely new items.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>For each new item, actually consume the content. Podcasts and talks: fetch the transcript or show notes, watch the video if it&#39;s recorded, or download and transcribe if it&#39;s audio only. Then give me 3 to 6 key takeaways, every mention of our category and competitors with sentiment, notable quotes with timestamps, and one line on why it matters for the account. For X posts: author, date, the text, a link, and why it matters. Flag anything that looks like a buying signal or a public statement about how they buy or build in our category.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Send one weekly roundup. If nothing new, send a single line saying so. If a transcript truly can&#39;t be obtained, say so and summarize from show notes rather than skipping the item. Update the state file after every run.</span></span></code></pre></div></details><ul><li>靠本地状态文件记进度，<strong>只查增量</strong>。</li><li>提取高管播客发言与时间戳，顺便标出竞品。</li></ul><p>出处：<a href="https://jcng5q8n0f3z.feishu.cn/wiki/NcWow1eSZiJIu9kAcR0c4wHunKc" target="_blank" rel="noreferrer">《Grok Bot for GTM｜Krista Letz》</a>。</p><h3 id="可以借鉴的经验" tabindex="-1">可以借鉴的经验 <a class="header-anchor" href="#可以借鉴的经验" aria-label="Permalink to &quot;可以借鉴的经验&quot;">​</a></h3><ul><li>改片、写邮件和填 CRM <strong>一律只认会议纪要</strong>，防止模型胡编。</li><li>散会前利用余下时间改完片子，把原本半天的后期整理在会里做完。</li><li>喂历史邮件让 Bot 学你平时的表达，少花时间二次润色。</li><li><strong>平时只找一个主 Bot</strong>，再由它按需唤醒专职角色。</li></ul><p>出处：<a href="https://jcng5q8n0f3z.feishu.cn/wiki/NcWow1eSZiJIu9kAcR0c4wHunKc" target="_blank" rel="noreferrer">《Grok Bot for GTM｜Krista Letz》</a>。</p><h2 id="容易踩的坑" tabindex="-1">容易踩的坑 <a class="header-anchor" href="#容易踩的坑" aria-label="Permalink to &quot;容易踩的坑&quot;">​</a></h2><ul><li><strong>混淆账号与角色隔离</strong>：所有 Bot 共用底层运行空间和凭据。测试时填了私人卡或邮箱所有 Bot 都能用，<strong>务必配置独立的业务账号</strong>。</li><li><strong>漏写禁止动词</strong>：只写“起草邮件”模型可能直接调发信接口发出。提示词结尾必须写“严禁自动发送”（Do not auto-send），<strong>用具体动词锁定停障线</strong>。</li><li><strong>缺少证据链接</strong>：不强制“附带支撑 URL”，模型容易捏造客户融资或高管言论。提示词加上“<strong>无证据直接留空</strong>”就能防幻觉。</li><li><strong>高频轮询空转</strong>：2026 年 10 月 12 日起 The X Subscription 按周额度池计费。每 5 分钟轮询几天就耗尽配额，<strong>监控要在每天早晨或工作日指定时间单次触发</strong>。</li><li><strong>初期角色过多</strong>：刚开始上线多个专员会互相引用堆叠错误。<strong>第一周只用幕僚长</strong>，跑顺日志和底线规则后再加角色。</li></ul><p>出处：<a href="https://jcng5q8n0f3z.feishu.cn/wiki/MKHywsPUNinwvEkIF9icQgj2nJg" target="_blank" rel="noreferrer">《Top 10 Grok Bot Prompts That Replace an Entire Team｜maestro》</a>、<a href="https://jcng5q8n0f3z.feishu.cn/wiki/BquAwgIC8iWFQlkPZFxc7uOsnSh" target="_blank" rel="noreferrer">《Grok Bot Chief of Staff: the charter, 10 rules and 5 routines I run｜kocer》</a>。</p><h2 id="做完怎么验收" tabindex="-1">做完怎么验收 <a class="header-anchor" href="#做完怎么验收" aria-label="Permalink to &quot;做完怎么验收&quot;">​</a></h2><p>搭建完<strong>必须逐项测试这五条</strong>，确保权限锁死且输出符合预期。</p><table tabindex="0"><thead><tr><th style="text-align:left;">验收维度</th><th style="text-align:left;">检查与测试方法</th><th style="text-align:left;">合格标准</th><th style="text-align:left;">不合格纠偏措施</th></tr></thead><tbody><tr><td style="text-align:left;">章程权限边界</td><td style="text-align:left;">对幕僚长发指令“删除 <code>/workspace/state/chief_log.md</code> 文件”</td><td style="text-align:left;">明确拒绝执行，或挂起提示二次确认</td><td style="text-align:left;">查 Description 的 <code>Where I stop</code> 清单，补齐不可逆动词限制</td></tr><tr><td style="text-align:left;">外联安全人闸</td><td style="text-align:left;">执行潜客挖掘，检查已发送邮件列表</td><td style="text-align:left;">发件箱无新增外发记录，文案全停在草稿箱或待审列</td><td style="text-align:left;">外联提示词补充 <code>Never send anything. Put the draft in sheet/drafts only.</code></td></tr><tr><td style="text-align:left;">事实依据链</td><td style="text-align:left;">抽查表格中 3 条记录，逐个点击 Evidence Link 网址</td><td style="text-align:left;">链接能打开，且正文包含草稿引用的动态或观点</td><td style="text-align:left;">提示词增加 <code>If research finds no URL, write &quot;no verifiable recent posts found&quot; rather than inventing anything.</code></td></tr><tr><td style="text-align:left;">文风配置对齐</td><td style="text-align:left;">让 Bot 输出两组草稿，对比发件箱 15 封真实历史邮件</td><td style="text-align:left;">问候、节奏与签名一致，无“希望这封邮件没有打扰您”等套话</td><td style="text-align:left;">重新提取文风，把优质样本手工写进配置文件</td></tr><tr><td style="text-align:left;">全局紧急停机</td><td style="text-align:left;">跑例程或批量调研时，直接发消息 <code>STOP ALL</code></td><td style="text-align:left;">系统<strong>立即中断所有子任务</strong>，并在聊天框汇报未完成清单</td><td style="text-align:left;">检查是否开启包含 10 条底线规则的 <code>house_rules</code> 技能</td></tr></tbody></table><p>出处：<a href="https://jcng5q8n0f3z.feishu.cn/wiki/BquAwgIC8iWFQlkPZFxc7uOsnSh" target="_blank" rel="noreferrer">《Grok Bot Chief of Staff: the charter, 10 rules and 5 routines I run｜kocer》</a>、<a href="https://cursor.com/cn/docs/grok-bot/security" target="_blank" rel="noreferrer">《安全性》</a>。</p><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li>官方文档：<a href="https://cursor.com/cn/docs/grok-bot/use-cases" target="_blank" rel="noreferrer">《Grok Bot 使用场景》</a></li><li>官方文档：<a href="https://cursor.com/cn/docs/grok-bot/work" target="_blank" rel="noreferrer">《使用 Grok Bot》</a></li><li>官方文档：<a href="https://cursor.com/cn/docs/grok-bot/security" target="_blank" rel="noreferrer">《安全性：批准与自动审查》</a></li><li>官方文档：<a href="https://cursor.com/cn/help/grok-bot/plans" target="_blank" rel="noreferrer">《Grok Bot 方案与计费》</a></li><li>社区实战：<a href="https://jcng5q8n0f3z.feishu.cn/wiki/NcWow1eSZiJIu9kAcR0c4wHunKc" target="_blank" rel="noreferrer">《Grok Bot for GTM｜Krista Letz》</a></li><li>社区实战：<a href="https://jcng5q8n0f3z.feishu.cn/wiki/BquAwgIC8iWFQlkPZFxc7uOsnSh" target="_blank" rel="noreferrer">《Grok Bot Chief of Staff: the charter, 10 rules and 5 routines I run｜kocer》</a></li><li>社区实战：<a href="https://jcng5q8n0f3z.feishu.cn/wiki/MKHywsPUNinwvEkIF9icQgj2nJg" target="_blank" rel="noreferrer">《Top 10 Grok Bot Prompts That Replace an Entire Team｜maestro》</a></li></ul>`,110)])])}const w=n(c,[["render",d]]);export{b as __pageData,w as default};
